            return new VersionRow(v.getVersion(), v.getFromDate() == null ? null : v.getFromDate().toString(),
                    v.getKey(), v.getValue() == null ? "" : v.getValue(), theirs.size(),
                    due.setScale(2, RoundingMode.HALF_UP).toPlainString());
        }).toList();
    }
}
